package test;

import org.eclipse.jface.preference.JFacePreferences;
import org.eclipse.jface.resource.ColorRegistry;
import org.eclipse.jface.resource.JFaceResources;
import org.eclipse.swt.graphics.Color;
import org.eclipse.swt.widgets.Control;
import java.util.Map;
import java.util.HashMap;

public class TestClass {
    public void method(Control parent) {
        // Not a ColorRegistry, should not match
        Map<String, Color> colorMap = new HashMap<>();
        Color someColor = colorMap.get("org.eclipse.ui.workbench.HOVER_FOREGROUND"); 

        // Different string literal key, should not match
        ColorRegistry colorRegistry = JFaceResources.getColorRegistry();
        Color otherColor = colorRegistry.get("some.other.key"); 

        // Already clean, should not match
        Color goodForeground = colorRegistry.get(JFacePreferences.INFORMATION_FOREGROUND_COLOR);
    }
}
